<template>
  <section class="flex flex-col gap-6">
    <RecruitmentMessageListFilters :params="params" :campaigns="campaignsForFilter" />
    <Card>
      <AppLoader v-if="isLoading" subject="messages" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load messages" variant="table" />
      <ResponsiveTable v-else rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead> Contact </ResponsiveTableHead>
          <ResponsiveTableHead> Subject </ResponsiveTableHead>
          <ResponsiveTableHead> Campaign </ResponsiveTableHead>
          <ResponsiveTableHead> Channel </ResponsiveTableHead>
          <ResponsiveTableHead> Type </ResponsiveTableHead>
          <ResponsiveTableHead> Status </ResponsiveTableHead>
          <ResponsiveTableHead> Created </ResponsiveTableHead>
          <ResponsiveTableHead> Sent </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableEmpty
            v-if="!data || data.items.length === 0"
            :colspan="8"
            :cols="4"
            :cols-sm="4"
            class="text-center"
          >
            <AppEmpty variant="table" subject="messages" />
          </ResponsiveTableEmpty>
          <ResponsiveTableRow
            v-for="message in data?.items"
            :key="message.id"
            :to="{ name: 'recruitment-messages-id', params: { id: message.id } }"
          >
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Contact">
              <span
                :title="message.staffing_contact_email"
                class="block truncate max-w-[10rem] sm:max-w-[14rem] md:max-w-[16rem]"
              >
                {{ message.staffing_contact_email }}
              </span>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Subject">
              <span
                :title="message.subject ?? undefined"
                class="block truncate max-w-[10rem] sm:max-w-[14rem] md:max-w-[18rem]"
                >{{ message.subject ?? '—' }}</span
              >
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Campaign">
              {{ message.campaign?.name ?? '—' }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Channel">
              <Badge :variant="getChannel(message.channel).variant">
                {{ getChannel(message.channel).label }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Type">
              <Badge :variant="getMessageType(message.message_type).variant">
                {{ getMessageType(message.message_type).label }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Status">
              <Badge :variant="getMessageStatus(message.effective_status).variant">
                {{ getMessageStatus(message.effective_status).label }}
              </Badge>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Created">
              {{ formatDateTzToFormat(message.created_at, 'MM/dd/yyyy, hh:mm aaa', timezone) }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="1" label="Sent">
              {{ message.sent_at ? formatDateTzToFormat(message.sent_at, 'MM/dd/yyyy, hh:mm aaa', timezone) : '—' }}
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter
          v-if="!error && !isLoading && data && data.total_count > 0"
          :colspan="8"
          :cols="4"
          :cols-sm="4"
        >
          <AppPagination :page="params.page" :total="data.total_count" :size="params.size" label="messages" />
        </ResponsiveTableFooter>
      </ResponsiveTable>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getRecruitmentMessageList,
  getSelectorRecruitmentCampaigns,
  type EmailAutomationType,
  type GetRecruitmentMessageListResponse,
  type GetSelectorRecruitmentCampaignsResponse,
  type DeliveryStatus,
  type RecruitmentChannel,
  type RecruitmentMessageSortBy,
  type RecruitmentMessageStatus,
  type RecruitmentMessageType,
  type SortType,
} from '~/client';
import { getMessageType } from '~/constants/recruitment/messageTypeConfig';
import { getMessageStatus } from '~/constants/recruitment/messageStatusConfig';
import { getChannel } from '~/constants/recruitment/channelStrategyConfig';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'messages',
});

useHead({
  title: 'Messages',
});

const route = useRoute('recruitment-messages');
const { timezone } = useUserRole();

const params = computed(() => {
  const queryParams = {
    ...parsePagination(route.query, { size: 50 }),
    sort_type: (route.query.sort_type as SortType) || 'desc',
    sort_by: (route.query.sort_by as RecruitmentMessageSortBy) || 'created_at',
    search_query: (route.query.search_query as string) || undefined,
    campaign_ids: processArrayQueryParameterFromUrl<string>(route.query.campaign_ids),
    message_types: processArrayQueryParameterFromUrl<RecruitmentMessageType>(route.query.message_types),
    channels: processArrayQueryParameterFromUrl<RecruitmentChannel>(route.query.channels),
    effective_statuses: processArrayQueryParameterFromUrl<DeliveryStatus | RecruitmentMessageStatus>(
      route.query.effective_statuses
    ),
    is_automated:
      route.query.is_automated === 'automated' || route.query.is_automated === 'manual'
        ? (route.query.is_automated as EmailAutomationType)
        : undefined,
    mentioned_project_ids: processArrayQueryParameterFromUrl<string>(route.query.mentioned_project_ids),
    created_at_from: (route.query.created_at_from as string) || undefined,
    created_at_to: (route.query.created_at_to as string) || undefined,
    timezone: timezone.value,
  };

  return Object.fromEntries(
    Object.entries(queryParams).filter(([_, value]) => value !== undefined)
  ) as typeof queryParams;
});

const { data, error, isLoading } = useQuery({
  key: () => ['recruitment-messages.list', params.value],
  query: (): Promise<GetRecruitmentMessageListResponse> =>
    getRecruitmentMessageList({ composable: '$fetch', query: ref(params.value) }),
  staleTime: 0,
});

const { data: filterCampaignsData } = useQuery({
  key: () => ['recruitment-campaigns.selector'] as const,
  query: (): Promise<GetSelectorRecruitmentCampaignsResponse> =>
    getSelectorRecruitmentCampaigns({ composable: '$fetch' }),
});

const campaignsForFilter = computed(() => filterCampaignsData.value?.items ?? []);
</script>
