import type { EmailAutomationType } from '~/client';

interface EmailAutomationEntry {
  label: string;
}

export const emailAutomationConfig: Record<EmailAutomationType, EmailAutomationEntry> = {
  automated: { label: 'Automated' },
  manual: { label: 'Manual' },
};

export function getEmailAutomation(type: EmailAutomationType): EmailAutomationEntry {
  return emailAutomationConfig[type] ?? { label: snakeCaseToCapitalizedCase(type) };
}

export const emailAutomationOptions: SelectItem<EmailAutomationType>[] = Object.entries(emailAutomationConfig).map(
  ([value, { label }]) => ({ name: label, value: value as EmailAutomationType })
);
